@import "tailwindcss";

@theme {
  --font-sans: "IBM Plex Sans", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --font-display: "Syne", "Avenir Next", "Segoe UI", sans-serif;
  --font-glaum: "Cormorant Garamond", "Palatino Linotype", Georgia, serif;
  --color-bg: #070605;
  --color-bg-elevated: #12100e;
  --color-bg-subtle: #1b1714;
  --color-fg: #e8e2d6;
  --color-muted: #9a9184;
  --color-subtle: #6f675c;
  --color-ember: #c45c28;
  --color-gold: #c9a36a;
  --color-cyan: #6ec8d4;
  --color-glaum: #d239f8;
  --color-glaum-soft: #e8b4ff;
  --color-glaum-gold: #c8a848;
  --color-shrimp: #ff8fa3;
  --color-prom: #f3ede6;
  --color-waheguru: #e8d7a3;
  --color-line: #e8e2d61a;
  --color-lamp: #7dffa3;
  --color-buzz: #ff3d9a;
  --shadow-border: 0 0 0 1px #e8e2d614;
  --shadow-filigree: 0 0 0 1px #c9a36a47, inset 0 0 0 1px #c9a36a14;
  --shadow-border-hover: 0 0 0 1px #c9a36a80, 0 12px 40px #00000073;
  --shadow-glaum: 0 0 0 1px #c8a84861, 0 0 48px #d239f847, 0 24px 60px #0000008c;
  --shadow-buzz: 0 0 0 1px #ff3d9a6b, 0 0 28px #ff3d9a38, 0 18px 40px #ff3d9a1f;
  --ease-out-smooth: cubic-bezier(.22, 1, .36, 1);
  --radius-xs: 4px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 26px;
}

@layer base {
  button:not(:disabled),
  [role="button"]:not(:disabled) { cursor: pointer; }
  html, body {
    background: var(--color-bg);
    color: var(--color-fg);
    font-family: var(--font-sans);
    overflow-x: clip;
    min-height: 100dvh;
    -webkit-font-smoothing: antialiased;
  }
  h1, h2, h3 { font-family: var(--font-display); text-wrap: balance; }
  :focus-visible { outline: 2px solid var(--color-gold); outline-offset: 3px; }
  input[type="range"] { accent-color: var(--color-ember); }
  .input {
    background: var(--color-bg);
    width: 100%;
    min-height: 2.75rem;
    color: var(--color-fg);
    box-shadow: var(--shadow-border);
    border-radius: 8px;
    padding: 0 12px;
  }
  .input::placeholder { color: var(--color-subtle); }
  textarea.input { resize: vertical; height: auto; min-height: 6rem; padding-top: 12px; padding-bottom: 12px; }
  select.input {
    appearance: none;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' height='8' viewBox='0 0 12 8'><path fill='%236f675c' d='M1 1l5 5 5-5'/></svg>");
    background-position: right 12px center;
    background-repeat: no-repeat;
    padding-right: 32px;
  }
  select.input option { background: var(--color-bg-elevated); color: var(--color-fg); }
}

.font-display { font-family: var(--font-display); }
.font-glaum { font-family: var(--font-glaum); }
.lamp { background: var(--color-subtle); border-radius: 999px; width: 10px; height: 10px; box-shadow: inset 0 0 0 1px #e8e2d633; }
.lamp-live { background: var(--color-lamp); box-shadow: 0 0 10px #7dffa3d9, 0 0 2px #7dffa3; }
.lamp-buzz { background: var(--color-buzz); animation: 1.1s ease-in-out infinite buzz-pulse; box-shadow: 0 0 10px #ff3d9af2, 0 0 22px #ff3d9a8c, 0 0 2px #fffacde6; }
.lamp-bezel { border: 1px solid #c9a36a8c; border-radius: 999px; place-items: center; width: 22px; height: 22px; display: grid; box-shadow: inset 0 0 0 1px #c9a36a33; }
.lamp-bezel-buzz { border-color: #ff3d9ab3; box-shadow: 0 0 18px #ff3d9a59, inset 0 0 0 1px #ff3d9a59; }
.filigree-frame { position: relative; }
.filigree-frame:before, .filigree-frame:after { content: ""; pointer-events: none; border: 1px solid #c9a36a73; width: 18px; height: 18px; position: absolute; }
.filigree-frame:before { border-bottom: 0; border-right: 0; top: 6px; left: 6px; }
.filigree-frame:after { border-top: 0; border-left: 0; bottom: 6px; right: 6px; }
.env-dot { width: 10px; height: 10px; border-radius: 999px; display: inline-block; }
.env-dot-on { background: var(--color-lamp); box-shadow: 0 0 8px #7dffa3cc; }
.env-dot-off { background: var(--color-subtle); }
body:before {
  content: "";
  pointer-events: none;
  z-index: 50;
  opacity: .045;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
  position: fixed;
  inset: 0;
}

