and-drift var(--station-drift,14s) ease-in-out infinite alternate;background:radial-gradient(circle at 30% 20%,#6ec8d438,#0000 36%),radial-gradient(circle at 70% 80%,#c45c2833,#0000 40%)}.station-motion-3{animation:sand-drift var(--station-drift,12s) ease-in-out infinite alternate;background:linear-gradient(115deg,#0000 30%,#c9a36a2e,#0000 70%)}.station-motion-thumb{opacity:.55}.station-motion-card{opacity:.72}.station-motion-hero{opacity:.88}.skin-glaum,.skin-waheguru{position:relative}.skin-glaum:after,.skin-waheguru:after{content:"";pointer-events:none;border-radius:inherit;mix-blend-mode:screen;opacity:.72;position:absolute;inset:0}.skin-glaum{box-shadow:var(--shadow-glaum);background:linear-gradient(#1a0a248c,#0a001459)}.skin-glaum:after{background-image:radial-gradient(circle at 18% 22%,#c8a848b3 0 1.2px,#0000 2.1px),radial-gradient(circle at 78% 38%,#d239f8b3 0 1.2px,#0000 2px),radial-gradient(circle at 42% 78%,#f3ede673 0 1px,#0000 2px),radial-gradient(circle at 62% 12%,#ff8fa373 0 1px,#0000 2px);background-size:26px 26px,16px 16px,34px 34px,22px 22px;animation:18s ease-in-out infinite alternate sand-drift}.skin-waheguru:after{background-image:radial-gradient(circle at 50% 20%,#e8d7a352 0 1.2px,#0000 2px),radial-gradient(circle at 30% 70%,#f6f0ff2e 0 1px,#0000 2px);background-size:22px 22px,40px 40px;animation:22s ease-in-out infinite alternate sand-drift}.station-glaum{mix-blend-mode:screen;background:radial-gradient(at 50% -8%,#d239f861,#0000 58%),radial-gradient(circle at 18% 78%,#c8a84838,#0000 42%),radial-gradient(circle at 82% 24%,#1a0a2459,#0000 46%);animation:16s ease-in-out infinite alternate sand-drift}.station-glaum-sequins{mix-blend-mode:screen;opacity:.75;background-image:radial-gradient(circle at 12% 18%,#fffacdf2 0 1px,#0000 2px),radial-gradient(circle at 38% 62%,#d239f8d9 0 1.1px,#0000 2.2px),radial-gradient(circle at 72% 28%,#c8a848e6 0 1px,#0000 2px),radial-gradient(circle at 88% 74%,#f3ede6b3 0 .8px,#0000 1.6px),radial-gradient(circle at 54% 44%,#ff8fa3b3 0 1px,#0000 2px);background-size:42px 42px,28px 28px,36px 36px,20px 20px,54px 54px;animation:3.6s ease-in-out infinite alternate sequin-twinkle}.station-glaum-shrimp{opacity:.55;mix-blend-mode:screen;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 40'><path fill='%23D239F8' fill-opacity='0.55' d='M8 22c8-12 24-16 38-8 8 4 14 4 20 0-6 8-16 14-30 14-10 0-18-2-22-6 2 5 10 10 20 10H10C4 32 2 26 8 22z'/><circle fill='%23FFFACD' cx='14' cy='16' r='1.4'/></svg>");background-position:12% 78%,78% 18%;background-repeat:no-repeat;background-size:72px 36px,48px 24px;animation:14s ease-in-out infinite alternate shrimp-drift}.station-wahe{mix-blend-mode:screen;background:radial-gradient(at 50% 0,#e8d7a347,#0000 55%),radial-gradient(circle at 70% 80%,#f6f0ff1f,#0000 40%)}.atmosphere-glaum{background:radial-gradient(at 50% 18%,#d239f829,#0000 55%),radial-gradient(at 50% 100%,#1a0a248c,#0000 60%);position:absolute;inset:0}.atmosphere-glaum-spark{background-image:radial-gradient(circle at 8% 18%,#c8a84847 0 1px,#0000 2px),radial-gradient(circle at 92% 22%,#d239f838 0 1px,#0000 2px),radial-gradient(circle at 14% 86%,#ff8fa329 0 1px,#0000 2px);background-size:90px 90px,70px 70px,110px 110px;animation:5s ease-in-out infinite alternate sequin-twinkle;position:absolute;inset:0}.atmosphere-glaum-shrimp{opacity:.35;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 40'><path fill='%23D239F8' fill-opacity='0.28' d='M8 22c8-12 24-16 38-8 8 4 14 4 20 0-6 8-16 14-30 14-10 0-18-2-22-6 2 5 10 10 20 10H10C4 32 2 26 8 22z'/></svg>");background-repeat:repeat;background-size:140px 70px;animation:22s linear infinite shrimp-drift;position:absolute;inset:-8%}.atmosphere-wahe{background:radial-gradient(at 50% 10%,#e8d7a314,#0000 50%);position:absolute;inset:0}.atmosphere-buzz{pointer-events:none;mix-blend-mode:screen;background:repeating-linear-gradient(#ff3d9a17 0 1px,#0000 1px 6px),radial-gradient(at 50% 108%,#ff3d9a47,#0000 62%),radial-gradient(at 8% 0,#ff3d9a1f,#0000 40%);animation:2.4s linear infinite buzz-scan;position:absolute;inset:0}.atmosphere-buzz-arc{pointer-events:none;background:linear-gradient(100deg,#0000 8%,#ff3d9a38 48%,#0000 78%);height:38%;animation:2.8s ease-in-out infinite buzz-flicker;position:absolute;inset:-8% 0 auto}.atmosphere-buzz-bolt{pointer-events:none;background:linear-gradient(90deg, transparent, var(--color-buzz), #ffd1ec, var(--color-buzz), transparent);height:2px;animation:1.1s linear infinite buzz-spark;position:absolute;inset:auto 8% 18%;box-shadow:0 0 18px #ff3d9ab3}.player-shell-glaum{background:#1a0a24eb;border-top-color:#c8a84859;box-shadow:0 -16px 40px #d239f829}.player-shell-glaum input[type=range]{accent-color:var(--color-glaum-gold)}.player-shell-wahe{box-shadow:0 -12px 28px #e8d7a314}.player-shell-buzz{background:#10060cf5;border-top-color:#ff3d9ad9;position:relative;box-shadow:0 -22px 48px #ff3d9a61,0 0 0 1px #ff3d9a47,inset 0 1px #ffd1ec40}.player-shell-buzz:after{content:"";pointer-events:none;box-shadow:8px 8px 0 -7px var(--color-buzz), -8px 8px 0 -7px var(--color-buzz), 8px -8px 0 -7px var(--color-buzz), -8px -8px 0 -7px var(--color-buzz);border:1px solid #ff3d9a38;position:absolute;inset:6px}.player-shell-buzz input[type=range]{accent-color:var(--color-buzz)}.player-bar-glaum{background:linear-gradient(90deg, var(--color-glaum), var(--color-glaum-gold), var(--color-shrimp));box-shadow:0 0 12px #d239f8a6}.player-bar-wahe{background:var(--color-waheguru)}.player-bar-buzz{background:linear-gradient(90deg, var(--color-buzz), #ffd1ec);box-shadow:0 0 12px #ff3d9ab3}.vu-meter{display:flex;align-items:flex-end;gap:3px;height:18px}.vu-meter span{display:block;width:4px;height:4px;border-radius:1px;background:var(--color-gold);opacity:.35}.vu-meter-on span{animation:vu-pulse 0.9s ease-in-out infinite alternate}.vu-meter-glaum span{background:linear-gradient(180deg, var(--color-glaum-gold), var(--color-glaum))}.glaum-title{font-family:var(--font-glaum);color:var(--color-glaum-gold);letter-spacing:-.01em;text-shadow:0 0 28px #d239f88c,0 0 64px #d239f838,0 4px 18px #000000a6}.love-layer{z-index:35;pointer-events:none;contain:strict;overflow-anchor:none;position:fixed;inset:0;overflow:hidden}.glaum-kicker{color:var(--color-glaum);letter-spacing:.32em}.glaum-sponsor{color:var(--color-prom);letter-spacing:.2em;opacity:.55}.btn-glaum{color:#fffacd;font-family:var(--font-glaum);letter-spacing:.14em;background:#c8a8481f;border:1px solid #c8a84899;border-radius:9999px}.btn-glaum-ghost{color:var(--color-prom);font-family:var(--font-glaum);letter-spacing:.14em;border:1px solid #f3ede62e;border-radius:9999px}.glaum-rule{background:linear-gradient(90deg,#0000,#d239f873,#0000);height:1px}.glaum-panel{box-shadow:var(--shadow-glaum);background:#0a001473;border:1px solid #c8a8482e}.dj-timer{color:var(--color-buzz);text-shadow:0 0 10px #ff3d9a8c}.drive-ring{color:var(--color-buzz);filter:drop-shadow(0 0 6px #ff3d9ad9)}.drive-bezel{border:1px solid #ff3d9ab3;border-radius:999px;place-items:center;width:28px;height:28px;display:grid;box-shadow:0 0 18px #ff3d9a59,inset 0 0 0 1px #ff3d9a59}.drive-ring-urgent{animation:.7s ease-in-out infinite buzz-pulse}.is-dj header{border-bottom-color:#ff3d9a8c;box-shadow:0 12px 36px #ff3d9a33}.mark-radio{text-transform:uppercase;letter-spacing:.28em}.is-dj .mark-radio{color:var(--color-buzz);text-shadow:0 0 18px #ff3d9aa6}.btn-buzz{color:var(--color-buzz);background:#ff3d9a29;border-radius:6px;box-shadow:0 0 0 1px #ff3d9a8c,0 0 18px #ff3d9a33}.buzz-spark{pointer-events:none;background:linear-gradient(90deg, transparent, var(--color-buzz), #ffd1ec, var(--color-buzz), transparent);inset-inline:0;background-size:220% 100%;height:2px;animation:1.8s linear infinite buzz-spark;position:absolute;top:0}.card-buzz{box-shadow:var(--shadow-buzz)}.booth-live{background:linear-gradient(180deg, #ff3d9a1a, transparent 46%), var(--color-bg-elevated);box-shadow:var(--shadow-buzz)}.skin-buzz{box-shadow:var(--shadow-buzz)}.lamp-on{color:var(--color-lamp);text-shadow:0 0 10px #7dffa3b3}@supports (color:color-mix(in lab, red, red)){.lamp-on{text-shadow:0 0 10px color-mix(in oklab, var(--color-lamp) 70%, transparent)}}.lamp-pink{color:var(--color-buzz);text-shadow:0 0 12px #ff3d9ab3}@supports (color:color-mix(in lab, red, red)){.lamp-pink{text-shadow:0 0 12px color-mix(in oklab, var(--color-buzz) 70%, transparent)}}.love-orb{bottom:calc(7.5rem + env(safe-area-inset-bottom,0px));min-width:4.5rem;max-width:7.5rem;min-height:4.5rem;font-family:var(--font-display);letter-spacing:.04em;text-align:center;will-change:transform, opacity;overflow-anchor:none;animation:love-float 5.1s var(--ease-out-smooth) forwards;border-radius:9999px;justify-content:center;align-items:center;padding:.6rem .7rem;font-size:.78rem;line-height:1.2;display:flex;position:absolute;pointer-events:auto;cursor:pointer}.love-orb-pop{min-width:2.4rem;min-height:2.4rem;font-family:var(--font-mono);letter-spacing:.14em;text-transform:uppercase;animation:love-pop 2.1s var(--ease-out-smooth) forwards;font-size:.65rem}.love-orb-glaum{color:var(--color-prom);text-shadow:0 0 12px #d239f88c;font-family:var(--font-glaum);background:radial-gradient(circle at 30% 24%,#fffacd8c,#0000 42%),radial-gradient(circle,#d239f852,#c8a8482e);box-shadow:0 0 0 1px #c8a84873,0 8px 22px #d239f847}.love-orb-wahe{color:var(--color-waheguru);background:radial-gradient(circle at 30% 24%,#f6f0ff66,#0000 42%),radial-gradient(circle,#e8d7a338,#07060533);box-shadow:0 0 0 1px #e8d7a347}@keyframes sequin-twinkle{0%{opacity:.35;transform:translate(0)}to{opacity:.85;transform:translateY(-4px)}}@keyframes shrimp-drift{0%{transform:translate(-2%,1%)}to{transform:translate(3%,-2%)}}@keyframes sand-drift{0%{transform:translate(0)}to{transform:translate(12px,-10px)}}@keyframes gear-spin{to{transform:rotate(360deg)}}@keyframes station-turn{to{transform:rotate(360deg)}}@keyframes love-float{0%{opacity:0;transform:translateY(12px)scale(.86)}12%{opacity:1}to{opacity:0;transform:translateY(-220px)scale(1.05)}}@keyframes love-pop{0%{opacity:0;transform:scale(.6)}20%{opacity:1;transform:scale(1.08)}to{opacity:0;transform:translateY(-48px)scale(.9)}}@keyframes buzz-pulse{0%,to{opacity:1;transform:scale(1)}50%{opacity:.65;transform:scale(1.18)}}@keyframes buzz-scan{0%{transform:translate(0)}to{transform:translateY(-7px)}}@keyframes buzz-flicker{0%,to{opacity:.55}18%{opacity:.9}22%{opacity:.4}48%{opacity:.85}62%{opacity:.5}}@keyframes buzz-spark{0%{background-position:100% 0}to{background-position:-100% 0}}@keyframes vu-pulse{0%{height:4px;opacity:.35}to{height:16px;opacity:1}}
@media (prefers-reduced-motion:reduce){.station-glaum,.station-glaum-sequins,.station-glaum-shrimp,.atmosphere-glaum,.atmosphere-glaum-spark,.atmosphere-glaum-shrimp,.atmosphere-buzz,.atmosphere-buzz-arc,.atmosphere-buzz-bolt,.lamp-buzz,.buzz-spark,.drive-ring-urgent,.vu-meter-on span,.love-orb,.love-orb-pop,.gear,.dial,.station-motion,.atmosphere-sand,.sand-grain{animation:none}}

.love-layer {
  z-index: 25;
  pointer-events: none;
  position: fixed;
  inset: 0;
  overflow: hidden;
}
.love-orb {
  --orb-drift: 12vw;
  --orb-size: 4.2rem;
  --orb-dur: 8s;
  position: absolute;
  bottom: calc(6.5rem + env(safe-area-inset-bottom, 0px));
  width: var(--orb-size);
  height: var(--orb-size);
  min-width: 0;
  min-height: 0;
  max-width: none;
  padding: 0.35rem 0.4rem;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-size: clamp(0.7rem, calc(var(--orb-size) * 0.22), 1.05rem);
  line-height: 1.1;
  border-radius: 9999px;
  pointer-events: auto;
  cursor: pointer;
  will-change: transform, opacity;
  animation: glaum-rise var(--orb-dur) var(--ease-out-smooth) forwards;
  touch-action: manipulation;
}
.love-orb-pop {
  width: 2.6rem;
  height: 2.6rem;
  min-width: 2.6rem;
  min-height: 2.6rem;
  font-size: 0.7rem;
  animation: glaum-pop 1.8s var(--ease-out-smooth) forwards;
}
.love-orb-glaum {
  backdrop-filter: blur(6px);
  font-family: var(--font-glaum), "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif;
}
@keyframes glaum-rise {
  0% { opacity: 0; transform: translate3d(0, 10vh, 0) scale(0.72) rotate(-6deg); }
  10% { opacity: 1; }
  55% { opacity: 1; }
  100% { opacity: 0; transform: translate3d(var(--orb-drift), -72vh, 0) scale(1.08) rotate(8deg); }
}
@keyframes glaum-pop {
  0% { opacity: 0; transform: scale(0.5); }
  18% { opacity: 1; transform: scale(1.12); }
  100% { opacity: 0; transform: translate3d(0, -10vh, 0) scale(0.86); }
}
@media (max-width: 640px) {
  .love-orb {
    bottom: calc(5.5rem + env(safe-area-inset-bottom, 0px));
  }
}
@media (prefers-reduced-motion: reduce) {
  .love-orb, .love-orb-pop { animation: none; opacity: 0.85; transform: none; }
}

.deck-scrub {
  position: relative;
  display: block;
  height: 2.75rem;
}
.deck-scrub input[type="range"] {
  position: absolute;
  inset: 0;
  z-index: 1;
  margin: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
  opacity: 0;
}
.deck-scrub input[type="range"]:disabled {
  cursor: not-allowed;
}
.deck-scrub-track {
  position: absolute;
  inset-inline: 0;
  top: 50%;
  height: 3px;
  transform: translateY(-50%);
  overflow: hidden;
  background: var(--color-line);
  border-radius: 999px;
  pointer-events: none;
}
.deck-scrub-track-thin {
  top: auto;
  bottom: 0;
  height: 3px;
  transform: none;
}
.deck-scrub-fill {
  display: block;
  height: 100%;
  background: var(--color-ember);
  border-radius: inherit;
}
.player-dock-seek {
  position: absolute;
  inset-inline: 0;
  top: 0;
  z-index: 2;
  height: 1.15rem;
}
.player-dock-seek input[type="range"] {
  position: absolute;
  inset: 0;
  z-index: 1;
  margin: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
  opacity: 0;
}
.player-dock-seek input[type="range"]:disabled {
  cursor: not-allowed;
}
.player-dock-seek .deck-scrub-track-thin {
  top: 0;
  bottom: auto;
  height: 2px;
  transform: none;
}
.player-sheet {
  max-height: min(85dvh, 42rem);
  overflow-y: auto;
  overscroll-behavior: contain;
}
.player-hero {
  width: min(100%, 16rem);
  margin-inline: auto;
}
.player-bar-wait {
  opacity: 0.7;
}
.listen-card {
  border-radius: var(--radius-md);
  padding: 0.85rem 1rem;
  box-shadow: var(--shadow-border);
  min-height: 4.5rem;
}
.listen-card-on {
  box-shadow: var(--shadow-filigree);
  background: var(--color-bg-subtle);
}
